$port = 8443; $listener = New-Object System.Net.HttpListener; $listener.Prefixes.Add("http://localhost:$port/"); try { $listener.Start(); Write-Host "=== HIVE RAG REST GATEWAY RUNNING ON PORT 8443 ===" -ForegroundColor Green; while ($listener.IsListening) { $context = $listener.GetContext(); $request = $context.Request; $response = $context.Response; $response.AddHeader("Access-Control-Allow-Origin", "*"); $response.ContentType = "application/json"; $output = if ($request.RawUrl -like "*/api/v1/health*") { @{ status = "HEALTHY"; service = "Hive RAG Gateway"; port = $port } | ConvertTo-Json } else { Get-Content "$env:USERPROFILE\hive-eds-360\trackers\social_engagement.json" -Raw }; $buffer = [System.Text.Encoding]::UTF8.GetBytes($output); $response.ContentLength64 = $buffer.Length; $response.OutputStream.Write($buffer, 0, $buffer.Length); $response.OutputStream.Close() } } finally { $listener.Stop() }
